#!/usr/bin/env python3
"""
generate-markdown.py
Generates a clean, beautifully formatted Markdown reference (Uma_nicknames.md)
from the structured uma_nicknames.json source of truth.
"""

import json
from pathlib import Path

def generate_markdown(json_path: Path, output_path: Path):
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    roster = data.get("uma_roster", [])
    metadata = data.get("metadata", {})
    rules = metadata.get("rules", [])

    lines = [
        "# 🐎 Umamusume Nicknames & Alias Directory",
        "",
        "> *Auto-generated from [`uma_nicknames.json`](./uma_nicknames.json). Do not edit this file directly.*",
        "",
        "There are many Umamusume in Tracen Academy, and keeping track of in-game callouts, fan nicknames, and crown names can be tricky. This directory provides an authoritative mapping.",
        "",
        "### 📜 Naming Conventions & Notes",
        ""
    ]

    for rule in rules:
        lines.append(f"- {rule}")

    lines.extend([
        "",
        f"**Total Registered Umamusume:** `{len(roster)}`",
        "",
        "| Canonical Name | In-Game Nicknames | Community / Fan Nicknames | Notes |",
        "| :--- | :--- | :--- | :--- |"
    ])

    for entry in roster:
        name = entry.get("name", "")
        in_game = ", ".join(entry.get("in_game_nicknames", []))
        community = ", ".join(entry.get("community_nicknames", []))
        notes = entry.get("notes", "")

        # Format empty columns cleanly
        in_game_str = in_game if in_game else "-"
        community_str = community if community else "-"
        notes_str = notes if notes else "-"

        lines.append(f"| **{name}** | {in_game_str} | {community_str} | {notes_str} |")

    lines.append("")

    with open(output_path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print(f"✅ Generated {output_path} ({len(roster)} entries)")

if __name__ == "__main__":
    base_dir = Path(__file__).parent.parent
    json_file = base_dir / "uma_nicknames.json"
    md_file = base_dir / "Uma_nicknames.md"
    generate_markdown(json_file, md_file)
